-- (1.1) [questID] = true: the quest giver never offers it (players reported it, /qd export line N)
ns.EXTRA_NOT_HERE = {
[9260]=true,
[94493]=true,
[97286]=true,
}
ns.EXTRA_NOT_HERE_COUNT = 3
ns.ATT_QUESTS = ns.ATT_QUESTS or {}
ns.ATT_OBJECTIVES = ns.ATT_OBJECTIVES or {}
-- (1.3.8, ATT a9d61d2 has Ira's Dagger and Merrick's Bow without faction, prerequisite and item start) a quest ATT
-- has keeps ATT's fields; the ones ATT leaves empty come from the open data
for id, q in pairs(ns.EXTRA_QUESTS) do local a = ns.ATT_QUESTS[id] if a == nil then ns.ATT_QUESTS[id] = q else for i = 1, 13 do if a[i] == nil then a[i] = q[i] end end if a[15] == nil then a[15] = q[15] end end end
ns.ATT_DUNGEONS = ns.ATT_DUNGEONS or {}
for id, d in pairs(ns.EXTRA_DUNGEONS) do local a = ns.ATT_DUNGEONS[id] if a == nil then ns.ATT_DUNGEONS[id] = d else for i = 1, 6 do if a[i] == nil then a[i] = d[i] end end end end
-- (1.3.4) ATT may list objectives without anything in them (98221 since ATT c269971): the open data fills those
local function EmptyObjective(v) return type(v) ~= "table" or ((not v[1] or #v[1] == 0) and (not v[2] or #v[2] == 0) and (not v[3] or #v[3] == 0)) end
for id, objs in pairs(ns.PATCH_OBJECTIVES) do local a = ns.ATT_OBJECTIVES[id] or {} for idx, v in pairs(objs) do a[idx] = v end ns.ATT_OBJECTIVES[id] = a end
-- (1.3.6) ATT keeps what it has; an ATT objective without mobs/objects or without places takes them from the open data
for id, o in pairs(ns.EXTRA_OBJECTIVES) do local a = ns.ATT_OBJECTIVES[id] if a == nil then ns.ATT_OBJECTIVES[id] = o else for idx, v in pairs(o) do if EmptyObjective(a[idx]) then a[idx] = v elseif type(a[idx]) == "table" then local w = a[idx] if (not w[1] or #w[1] == 0) and type(v[1]) == "table" and #v[1] > 0 then w[1] = v[1] end if (not w[3] or #w[3] == 0) and type(v[3]) == "table" and #v[3] > 0 then w[3] = v[3] end end end end end
for id, pre in pairs(ns.EXTRA_PREREQS) do local q = ns.ATT_QUESTS[id] if q then q[6] = pre end end
for id, lv in pairs(ns.EXTRA_LEVELS) do local q = ns.ATT_QUESTS[id] if q then q[5] = lv end end
for id, p in pairs(ns.EXTRA_STARTS) do local q = ns.ATT_QUESTS[id] if q then q[1], q[2], q[3] = p[1], p[2], p[3] end end
for id, g in pairs(ns.EXTRA_GIVERS) do local q = ns.ATT_QUESTS[id] if q then q[7] = g end end
for id, r in pairs(ns.EXTRA_RACES) do local q = ns.ATT_QUESTS[id] if q then q[10] = r end end
for id, c in pairs(ns.EXTRA_CLASSES) do local q = ns.ATT_QUESTS[id] if q then q[9] = c end end
for id, f in pairs(ns.EXTRA_FACTION) do local q = ns.ATT_QUESTS[id] if q then q[4] = f or nil end end
for id in pairs(ns.EXTRA_ITEM_STARTS) do local q = ns.ATT_QUESTS[id] if q then q[7] = nil q[8] = ((q[8] or ""):gsub("i", "")) .. "i" end end
for id, n in pairs(ns.EXTRA_NEED) do local q = ns.ATT_QUESTS[id] if q then q[11] = n end end
for id, sk in pairs(ns.EXTRA_SKILL) do local q = ns.ATT_QUESTS[id] if q then q[12] = sk ~= 0 and sk or nil end end
-- (round 5) flags the ATT data has wrong ("" = none)
ns.EXTRA_FLAGS = {[311]="i",[1442]="",[1655]="",[1793]="",[1794]="",[8391]="r",[8392]="r",[8397]="r",[8398]="r",[94472]="r",[94473]="r",[94616]="r",}
for id, f in pairs(ns.EXTRA_FLAGS) do local q = ns.ATT_QUESTS[id] if q then q[8] = f ~= "" and f or nil end end
for id, d in pairs(ns.EXTRA_QUEST_DUNGEONS) do local q = ns.ATT_QUESTS[id] if q then q[15] = d end end
for id, add in pairs(ns.EXTRA_SERIES_PREREQS) do
  local q = ns.ATT_QUESTS[id]
  if q and q[11] == nil then
    local pre = type(q[6]) == "table" and q[6] or {}
    for _, p in ipairs(add) do
      local has = false
      for _, x in ipairs(pre) do if x == p then has = true end end
      if not has and p ~= id then pre[#pre + 1] = p end
    end
    if #pre > 0 then q[6] = pre end
  end
end
for id, add in pairs(ns.LEARNED_PREREQS) do
  local q = ns.ATT_QUESTS[id]
  if q and q[11] == nil then
    local pre = type(q[6]) == "table" and q[6] or {}
    for _, p in ipairs(add) do
      local has = false
      for _, x in ipairs(pre) do if x == p then has = true end end
      if not has and p ~= id then pre[#pre + 1] = p end
    end
    if #pre > 0 then q[6] = pre end
  end
end
for id, objs in pairs(ns.LEARNED_OBJECTIVES) do
  local o = ns.ATT_OBJECTIVES[id] or {}
  for idx, v in pairs(objs) do
    local a = o[idx]
    if a == nil then o[idx] = v
    elseif (not a[1] or #a[1] == 0) and (not a[3] or #a[3] == 0) then
      -- (1.3.5) the data names only the item: the learned spots and mobs are its places
      a[3] = v[3]
      if v[1] and #v[1] > 0 then a[1] = v[1] end
    end
  end
  ns.ATT_OBJECTIVES[id] = o
end
-- (1.3.6) objectives that name only their item: who drops it and where it lies (CMaNGOS), if nothing else has a place
for id, objs in pairs(ns.ATT_OBJECTIVES) do
  for _, a in pairs(objs) do
    if type(a) == "table" and (not a[1] or #a[1] == 0) and (not a[3] or #a[3] == 0) and type(a[2]) == "table" then
      local cr, pts = {}, {}
      for _, it in ipairs(a[2]) do
        local s = ns.ITEM_SOURCES[it]
        if s then
          for _, c in ipairs(s[1]) do cr[#cr + 1] = c end
          for _, v in ipairs(s[2]) do pts[#pts + 1] = v end
        end
      end
      if #cr > 0 then a[1] = cr end
      if #pts > 0 then a[3] = pts end
    end
  end
end
